(function(){
'use strict';
const C=window.COURSE,E=window.BioEngine,$=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const chapter=id=>C.chapters.find(x=>x.id===id);
let state=E.fresh(),storageOK=true,route='',review=null,diagnosticPos=0,shown=new Set(),spoken=new Set(),examChecks={},reviewFilter='weak',reviewChapter='',examFilter='',day=1,courseFilter='';
try{const raw=localStorage.getItem(E.KEY);if(raw)state=E.validateImport(JSON.parse(raw),C);localStorage.setItem(E.KEY,JSON.stringify(state));}catch(error){storageOK=false;}
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(state));storageOK=true;$('#storage-warning').hidden=true;}catch(error){storageOK=false;$('#storage-warning').hidden=false;}$('#save-status').textContent=storageOK?'Sparat på den här enheten':'Lagring är inte tillgänglig';}
$('#storage-warning').hidden=storageOK;
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4400);}
const button=(label,path,cls='')=>`<a class="button ${cls}" href="#${path}">${label}${icon('arrow')}</a>`;
const title=(eyebrow,h,p)=>`<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const pill=(level='must')=>`<span class="pill ${level}">${level==='must'?'MÅSTE KUNNA':level==='deep'?'VIKTIG FÖRDJUPNING':'OM TID FINNS'}</span>`;
const back=(name,path)=>`<a class="back" href="#${path}">${icon('arrow')}${name}</a>`;
const formatMinutes=n=>n>=60?`${Math.floor(n/60)} h ${n%60?`${n%60} min`:''}`.trim():`${n} min`;
function navigate(path){location.hash=path;}
function summaryStats(){const secure=C.cards.filter(x=>state.cards[x.id]?.rating===2).length;const rated=C.cards.filter(x=>state.cards[x.id]).length;const exams=Object.keys(state.exams).length;return {secure,rated,exams};}
function statsHTML(){const s=summaryStats();return `<section class="stats" aria-label="Din självskattade progression"><div class="stat"><span class="stat-label">Trygga kärnfrågor</span><strong>${s.secure}<small> / 28 självskattade</small></strong><span class="mini-icon">${icon('check')}</span><div class="progress-track" role="progressbar" aria-label="Självskattat säkra kärnfrågor" aria-valuemin="0" aria-valuemax="28" aria-valuenow="${s.secure}"><span style="width:${s.secure/28*100}%"></span></div></div><div class="stat"><span class="stat-label">Effektiv studietid kvar</span><strong data-remaining-display>${formatMinutes(E.remain(state))}</strong><span class="mini-icon">${icon('clock')}</span><button class="quiet fine" data-action="settings" style="padding:2px 0;display:block;min-height:30px">Anpassa till din tid ↗</button></div><div class="stat"><span class="stat-label">Egna svar, självbedömda</span><strong>${s.exams}<small> / 12 öppna provfrågor</small></strong><span class="mini-icon">${icon('pen')}</span><p class="fine" style="margin:7px 0 0">Kvalitet före antal.</p></div></section>`;}
function cellArt(){return `<div class="hero-art"><svg viewBox="0 0 380 295" role="img" aria-label="Förenklad eukaryot cell med kärna, mitokondrier, ER och membran. Länkarna öppnar motsvarande förklaring."><defs><pattern id="dot-grid" width="19" height="19" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#dce3d1"/></pattern></defs><rect width="380" height="295" fill="url(#dot-grid)"/><path d="M89 66C121 15 248 26 291 64S352 182 304 230 158 282 91 236 39 121 89 66Z" fill="#e0e9c9" stroke="#719064" stroke-width="1.7"/><path d="M96 72C130 25 245 36 285 72S339 178 298 222 160 270 99 229 49 125 96 72Z" fill="#edf1de" stroke="#a3b88b" stroke-width="1"/><g fill="none" stroke="#c2d1a5" stroke-width="3" stroke-linecap="round"><path d="M105 110q25-38 50-24m-55 37q22-38 53-25m-48 40q22-39 50-26m-42 39q21-29 45-22"/><path d="M127 209q30 12 51-2m-51 12q30 12 51-2m-47 12q26 12 49-2"/></g><a href="#chapter/celler"><circle cx="201" cy="134" r="44" fill="#cfdfae" stroke="#8da66b" stroke-width="1.5"/><circle cx="205" cy="138" r="17" fill="#a7c079"/><path d="M175 120q22-17 40 1m-40 27q10 16 27 14m12-54q15 3 19 19" fill="none" stroke="#a0b97a" stroke-width="1.3"/></a><g fill="#dfbd7d" stroke="#b99559" stroke-width="1.2"><a href="#chapter/celler"><ellipse cx="279" cy="124" rx="16" ry="28" transform="rotate(25 279 124)"/></a><ellipse cx="119" cy="182" rx="16" ry="25" transform="rotate(-35 119 182)"/></g><g stroke="#b18b4b" fill="none"><path d="m276 101-4 14 10 1-15 13 11 2-8 12M104 168l10 1-3 11 14-3-2 15 12-1"/></g><g fill="#adc28b"><circle cx="245" cy="196" r="9"/><circle cx="151" cy="72" r="5"/><circle cx="281" cy="179" r="6"/><circle cx="91" cy="145" r="4"/></g><g fill="#7c995c"><circle cx="142" cy="155" r="2"/><circle cx="150" cy="168" r="2"/><circle cx="261" cy="89" r="2"/><circle cx="257" cy="218" r="2"/><circle cx="178" cy="187" r="2"/><circle cx="302" cy="154" r="2"/></g><g stroke="#91a377" stroke-width=".8" fill="none"><path d="M218 121h65l30-28h49M113 181H58l-15 20H8M164 97H91L62 62H14M295 211l28 30h49"/></g><g fill="#59734d" font-family="Segoe UI, sans-serif" font-size="9"><text x="313" y="85">CELLKÄRNA</text><text x="9" y="216">MITOKONDRIE</text><text x="15" y="55">KORNIGT ER</text><text x="298" y="255">MEMBRAN</text></g></svg><div class="art-caption">STRUKTUR → FUNKTION → SAMBAND</div></div>`;}
function topicCard(c){const s=E.chapterStats(state,C,c.id);return `<a class="topic-link" href="#chapter/${c.id}"><span class="topic-number">${c.n}</span><div><h3>${c.title}</h3><p>${s.rated?`${s.secure}/4 trygga · ${s.missed?s.missed+' missade provpoänger':'fortsätt förklara'}`:'Kärnmodell + 4 frågor'} · riktmärke ${c.minutes} min</p></div>${icon('arrow')}</a>`;}
function nextSession(){return C.sessions.find(s=>s.tasks.some(t=>!state.tasks[t[0]]))||null;}
function home(){const next=nextSession(),a=E.adaptive(state,C);if(a.mode==='minimum'&&state.diagnosed)return shortHome(a);return `<section class="hero"><div><span class="eyebrow">BIOLOGI 2 · DITT TVÅDAGARSPROGRAM</span><h1>Förstå sambanden.<br><span>Skriv bättre provsvar.</span></h1><p>Sju områden, en tydlig väg. Lär mekanismerna, plocka fram dem ur minnet och använd dem i egna resonemang.</p><div class="actions">${button(state.diagnosed?(next?'Fortsätt där du är':'Repetera det viktiga'):'Starta första passet',state.diagnosed?(next?'session/'+next.id:'review'):'session/1')}${button('Se din studieplan','plan','secondary')}</div></div>${cellArt()}</section>${statsHTML()}<div class="two-cols"><section class="next-card"><span class="eyebrow">${state.diagnosed?'DIN NÄSTA AKTIVITET':'BÖRJA HÄR · 10 MINUTER'}</span><h2>${state.diagnosed?(next?next.title:'Håll mekanismerna levande'):'Ta reda på vad du redan kan.'}</h2><p>${state.diagnosed?(next?next.goal:'Återkalla dina osäkra frågor och använd dem i ett nytt scenario.'):'Sju korta frågor visar var du ska lägga kraften. Förklara först med egna ord. Det är helt okej att markera ”Inte kan”.'}</p><div class="session-meta">${state.diagnosed&&next?`DAG ${next.day} · ${next.time} · ${next.effective} EFFEKTIVA MINUTER`:'EN FRÅGA PER OMRÅDE · UTAN BETYGSPOÄNG'}</div>${button(state.diagnosed?'Öppna nästa steg':'Gör snabbdiagnosen',state.diagnosed?(next?'session/'+next.id:'review'):'diagnostic','light')}</section><section class="card"><div class="small-intro">${icon('link')} DIN VIKTIGASTE TANKEMODELL</div><h3>Vad passerar?<br>Vad driver det?<br>Vad blir följden?</h3><p>En säker orsakskedja hjälper dig även när provfrågan ser helt ny ut.</p><a class="fine" href="#connections">Träna biologiska samband →</a></section></div><div class="section-top"><h2>Två dagar med plats för livet.</h2><a href="#plan">Hela schemat →</a></div><div class="schedule-preview"><div class="day-preview"><div class="day-title"><h3>Måndag 2 nov</h3><span>235 min effektivt</span></div><p>Grundmodeller, transport, mikrober och resistens.</p>${C.sessions.filter(x=>x.day===1).map(s=>`<div class="day-line"><span>${s.time.slice(0,5)}</span><i class="dot"></i><a href="#session/${s.id}">${s.title}</a></div>`).join('')}</div><div class="day-preview"><div class="day-title"><h3>Tisdag 3 nov</h3><span>125 min effektivt</span></div><p>Återkallning, växtcellen, egna provsvar och luckor.</p>${C.sessions.filter(x=>x.day===2).map(s=>`<div class="day-line"><span>${s.time.slice(0,5)}</span><i class="dot"></i><a href="#session/${s.id}">${s.title}</a></div>`).join('')}<p style="margin-top:17px">Fotboll 16:30–19:00. Sen kväll? Förkorta passet och behåll sömnen.</p></div></div><div class="section-top"><h2>Din biologiska verktygslåda.</h2><a href="#course">Utforska kursen →</a></div><div class="topic-grid">${C.chapters.map(topicCard).join('')}</div>${a.time<200?`<div class="info-strip space-top">${icon('clock')}Du har ${a.time} effektiva minuter kvar. Den anpassade planen prioriterar kärnmodeller och egna svar. <a href="#plan">Öppna planen</a></div>`:''}`;}
function shortHome(a){const t=a.tasks[0];return `${title('ANPASSAT EFTER DIN TID','En viktig sak i taget.',`Du har ${a.time} effektiva minuter kvar. Börja med kärnmodellen som planen prioriterar och kontrollera den utan stöd.`)}${statsHTML()}<section class="next-card"><span class="eyebrow">NÄSTA STEG · ${t?.minutes||0} MINUTER</span><h2>${t?.title||'Avsluta och återhämta dig.'}</h2><p>Alla sju områden finns kvar. Den korta planen väljer det som ryms nu och behåller utrymme för egna svar.</p>${button('Börja nu',t?.route||'plan','light')}</section><div class="actions space-top">${button('Se anpassad studieplan','plan','secondary')}${button('Mina kunskapsluckor','progress','secondary')}</div>`;}
function plan(){const a=E.adaptive(state,C);return `${title('TID ÄR EN RESURS','En plan som går att genomföra.','Standard: 235 effektiva minuter på måndagen och 125 på tisdagen. Alla angivna pauser ligger utanför de 360 effektiva minuterna.')}<div class="programme" aria-label="Välj tid som utgångspunkt">${[['minimum','Minimiprogram','180 min · alla sju kärnor',180],['standard','Standardprogram','360 min · huvudspåret',360],['extra','Extraprogram','450 min · mer resonemang',450]].map(([id,label,sub,min])=>`<button data-action="programme" data-minutes="${min}" aria-pressed="${a.mode===id}"><strong>${label}</strong><small>${sub}</small></button>`).join('')}</div><p class="fine">Knapparna anger hur mycket effektiv tid du har kvar från nu. Timern drar sedan av faktisk fokustid. Läsning av extra material ska rymmas i vald budget.</p><section class="card"><div class="section-top" style="margin-top:0"><h2>Din prioritering just nu</h2><button class="button secondary small" data-action="settings">Ändra tid</button></div><p>${a.time} minuter fördelas efter självskattade luckor, missade provpoänger och vilka modeller som behövs för resten. Detta är ett förslag, inte en automatisk kunskapsbedömning.</p><ol class="task-list">${a.tasks.map(t=>`<li><div><a href="#${t.route}">${t.title}</a><small>${t.minutes} min · ${t.priority==='must'?'MÅSTE KUNNA':'VIKTIG FÖRDJUPNING'}</small></div><a class="button secondary small" href="#${t.route}">Öppna →</a></li>`).join('')}</ol>${a.time<100?'<p class="fine">Tiden räcker inte till lika mycket i alla områden. Börja med den svagaste mekanismen och behåll ett kort eget provsvar. Listan visar vad som ryms; den lovar inte full täckning.</p>':''}${a.mode==='extra'?'<p class="fine">Extra: utveckla svar med alternativa förklaringar, försök och modellbegränsningar. Välj särskilt frågorna Resistensen stannar kvar, Membranets regler byter villkor och Testa en förklaring om konservering.</p>':''}</section><div class="section-top"><h2>Huvudschemat · standardprogram</h2></div><div class="tabs" aria-label="Välj studiedag"><button data-action="day" data-day="1" aria-pressed="${day===1}">Dag 1 · måndag</button><button data-action="day" data-day="2" aria-pressed="${day===2}">Dag 2 · tisdag</button></div><div class="info-strip">${icon('clock')} ${day===1?'Hemma cirka 14:20. Ät och landa först. Dela 75-minutersfönstren i kortare fokusblock och ta 10 minuters paus inom varje fönster.':'Hemma cirka 13:40–14:00. Ät före start. Fotboll 16:30–19:00. Om kvällen börjar 21:00: välj 25 effektiva minuter, exempelvis 10 min egna svar + 15 min luckor, och sluta 21:30.'}</div><div class="session-list">${C.sessions.filter(s=>s.day===day).map(s=>{const done=s.tasks.every(t=>state.tasks[t[0]]);return `<article class="card session-card ${done?'done':''}"><div class="session-time">${s.time}<small>${s.effective} min fokus<br>${s.pause} min pauser</small></div><div><span class="eyebrow">PASS ${s.id}</span><h3>${s.title}</h3><p>${s.goal}</p><p class="fine">Kontroll: ${s.check}</p></div><div class="actions">${done?'<span class="check-circle">✓</span>':''}${button('Öppna passet','session/'+s.id,'secondary small')}</div></article>`}).join('')}</div><section class="card space-top"><h3>Om du blir trött eller hamnar efter</h3><p>Sänk återstående tid i inställningarna. Börja med en tvåminutersstart: öppna en fråga och säg vad du vet. Låt sedan ett 15-minutersblock räcka för en mekanism. När du redan kan: gör kärnfrågorna direkt och gå vidare när du själv kan motivera svaren utan stöd.</p><p>På tisdag kväll: återkalla först, läs bara för att reparera ett konkret fel och försök sedan igen utan stöd. Flytta inte stora delar av nyinlärningen till en sen kväll.</p></section>`;}
function sessionPage(id){const s=C.sessions.find(x=>x.id===+id);if(!s)return missing();return `${back('Studieplan','plan')}${title('DAG '+s.day+' · PASS '+s.id,s.title,`${s.time} · ${s.effective} effektiva minuter + ${s.pause} minuters pauser.`)}<div class="two-cols"><section class="card"><h3>Det här ska du kunna efteråt</h3><p>${s.goal}</p><h3>Varför just nu?</h3><p>${s.why}</p><h3>Gör i den här ordningen</h3><ul class="task-list">${s.tasks.map(([id,label,min,path])=>`<li><input type="checkbox" id="task-${id}" data-task="${id}" ${state.tasks[id]?'checked':''}><label for="task-${id}"><a href="#${path}">${label}</a><small>${min} min · markerar genomförd aktivitet, inte säker kunskap</small></label>${button('Börja',path,'secondary small')}</li>`).join('')}</ul><div class="actions"><button class="button" data-action="focus">${icon('clock')} Starta ${state.focusLength} min fokus</button>${button(s.id===6?'Till repetition':'Till nästa pass',s.id===6?'review':'session/'+(s.id+1),'secondary')}</div></section><aside><section class="card"><span class="pill must">OBLIGATORISKT</span><h3 class="space-top">Lär → återkalla → kontrollera</h3><p>${s.check}</p><hr><span class="pill extra">KAN HOPPAS ÖVER</span><p class="space-top">${s.skip}</p></section><div class="info-strip space-top">${icon('leaf')}<span>${s.next}</span></div></aside></div>`;}
function course(){return `${title('SJU OMRÅDEN · INGET ANNAT','Lär mekanismen. Testa direkt.','Varje område har sex steg, fyra kärnfrågor och tydligt avgränsad fördjupning. Riktmärkena är ämnesandelar; de är inga extra pass utöver schemat.')}<div class="filter-row"><label for="course-search">Hitta område eller begrepp</label><input id="course-search" type="search" placeholder="Till exempel ribosom eller turgor" value="${esc(courseFilter)}" style="border:1px solid var(--line);border-radius:9px;padding:10px 14px;width:320px"></div><div class="topic-grid" id="topic-results">${filteredChapters()}</div><div class="info-strip space-top">${icon('check')}Kan du redan ett område? Öppna ”Testa direkt” i kapitlet. En säker markering bygger på att du kan förklara själv, utan facit.</div>`;}
function filteredChapters(){const q=courseFilter.toLocaleLowerCase('sv');const list=C.chapters.filter(c=>[c.title,...c.terms].join(' ').toLocaleLowerCase('sv').includes(q));return list.map(topicCard).join('')||'<p class="muted">Inget område matchar. Prova ett annat begrepp.</p>';}
function osmosisLab(){return `<section class="lab" aria-labelledby="osmos-lab-title"><span class="eyebrow">VISUELL FÖRKLARING</span><h3 id="osmos-lab-title">Förutsäg innan du drar.</h3><p>Vart går vattnet? Ändra halten utanför och jämför celltyperna. Modellen antar vattenpermeabla membran och ämnen som inte passerar under den visade tiden.</p><label for="osm-range">Effektiv partikelhalt utanför · <output id="osm-value">300</output> mOsm/L</label><input id="osm-range" type="range" min="100" max="600" step="25" value="300"><div class="lab-presets"><button data-action="osm-preset" data-value="150">Hypoton</button><button data-action="osm-preset" data-value="300">Isoton referens</button><button data-action="osm-preset" data-value="500">Hyperton</button></div><div class="lab-art"><div class="lab-cell"><svg viewBox="0 0 220 170" role="img" aria-label="Förenklad blodkropp, volymen ändras med omgivningens halt"><ellipse id="rbc" cx="110" cy="86" rx="43" ry="35" fill="#d2a28e" stroke="#a77866" stroke-width="2"/><ellipse id="rbc-center" cx="110" cy="86" rx="21" ry="15" fill="#e6c5b7"/><text id="rbc-flow" x="110" y="155" text-anchor="middle" font-size="13" fill="#4b6850">Vatten ⇄</text></svg><strong>Röd blodkropp</strong></div><div class="lab-cell"><svg viewBox="0 0 220 170" role="img" aria-label="Förenklad växtcell med stel vägg, membran och vakuol"><rect x="43" y="27" width="134" height="111" rx="18" fill="none" stroke="#758b4e" stroke-width="7"/><rect id="plant-membrane" x="49" y="33" width="122" height="99" rx="14" fill="#dbe8bc" stroke="#718b53" stroke-width="2"/><rect id="vacuole" x="66" y="48" width="88" height="69" rx="18" fill="#b6cf9a"/><text id="plant-flow" x="110" y="155" text-anchor="middle" font-size="13" fill="#4b6850">Vatten ⇄</text></svg><strong>Växtcell</strong></div></div><div class="lab-result" id="osm-result" aria-live="polite"></div><p class="fine" style="margin:12px 0 0">Referensen är 300 mOsm/L inne före förändringen. Storlek och gränser är schematiska; detta är ingen kvantitativ cell- eller medicinsk simulering.</p></section>`;}
const pumpSteps=[['Bind på insidan','Tre Na⁺ binder till pumpens inåtvända bindningsställen.','3 Na⁺ →'],['Använd ATP','ATP hydrolyseras. Pumpen fosforyleras och ändrar form.','ATP → ADP + Pᵢ'],['Släpp ut Na⁺','Den utåtvända formen avger tre Na⁺ till utsidan.','3 Na⁺ ut'],['Bind på utsidan','Två K⁺ binder till den utåtvända pumpen.','← 2 K⁺'],['Återställ formen','Fosfat avges och pumpen återgår till inåtvänd form.','Pᵢ avges'],['Släpp in K⁺','Två K⁺ avges inne. Ett varv: 3 Na⁺ ut, 2 K⁺ in, 1 ATP.','2 K⁺ in']];let pumpPos=0;
function pumpLab(){const p=pumpSteps[pumpPos];return `<section class="lab" aria-labelledby="pump-title"><span class="eyebrow">STEG FÖR STEG</span><h3 id="pump-title">Säg nästa steg innan du klickar.</h3><div class="pump-dots">${pumpSteps.map((x,i)=>`<i class="${i<=pumpPos?'on':''}"></i>`).join('')}</div><div class="pump-stage"><div class="pump-art"><div class="pump-core" style="transform:rotate(${pumpPos>1&&pumpPos<5?7:0}deg)">${p[2]}</div></div><div aria-live="polite"><small class="fine">${pumpPos+1} / 6 · Na⁺/K⁺-pumpen</small><h4>${p[0]}</h4><p>${p[1]}</p></div></div><div class="actions"><button class="button secondary small" data-action="pump-prev" ${pumpPos===0?'disabled':''}>← Förra</button><button class="button small" data-action="pump-next">${pumpPos===5?'Börja om':'Nästa steg →'}</button></div><p class="fine space-top">Formändringen visas schematiskt. Pumpen arbetar mot jongradienter och är skild från en öppen jonkanal.</p></section>`;}
function chapterPage(id){const c=chapter(id);if(!c)return missing();const own=C.cards.filter(x=>x.chapter===id);const limited=E.remain(state)<=200;return `${back('Alla sju områden','course')}${title(c.n+' · '+c.source,c.title,c.why)}<div class="actions">${pill()}<span class="fine">Riktmärke ${c.minutes} min inklusive återkallning</span><a class="button secondary small" href="#chapter/${id}/test">Testa direkt →</a></div><div class="teaching-layout space-top"><article><section aria-label="Undervisning i sex steg">${c.steps.map((s,i)=>`<section class="lesson-step" id="step-${i+1}"><span class="step-number">${i+1}</span><div><h2>${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}</div></section>`).join('')}</section>${id==='osmos'?osmosisLab():id==='aktiv'?`<div id="pump-lab">${pumpLab()}</div>`:''}<div class="misconception"><h3>Vanliga provfällor</h3><ul>${c.traps.map(x=>`<li>${x}</li>`).join('')}</ul></div><details class="details-block"><summary>${pill('deep')} Fördjupa modellen när kärnan sitter</summary>${limited?'<p class="fine">Du har valt en kort tidsbudget. Öppna detta först om kärnfrågorna redan känns säkra.</p>':''}${c.deeper.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}</details><details class="details-block"><summary>${pill('extra')} Extra från boken och lektionen</summary>${c.extra.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}</details><section id="chapter-questions"><div class="section-top"><h2>Förklara utan stöd.</h2><span class="fine">4 kärnfrågor</span></div><p class="fine">Skriv en kort förklaring, säg den högt eller markera ärligt att du inte kan ännu. Visa sedan svaret och självskatta.</p>${own.map(cardHTML).join('')}</section><div class="actions">${button('Träna ett öppet provsvar','exams/'+id)}${button('Repetera svagaste frågorna','review','secondary')}</div></article><aside class="lesson-index"><nav aria-label="Kapitlets steg">${c.steps.map((s,i)=>`<a href="#chapter/${id}/step-${i+1}" data-scroll="step-${i+1}">${i+1}. ${s[0]}</a>`).join('')}<a href="#chapter/${id}/test">→ Kontrollera förståelsen</a></nav><section class="card space-top"><h3>Ord att använda precist</h3><div class="term-cloud">${c.terms.map(t=>`<span>${t}</span>`).join('')}</div><p>Förklara vad orden gör i processen. En lista med begrepp ersätter inte en mekanism.</p></section><section class="card space-top"><h3>Relevant provträning</h3>${C.exams.filter(e=>e.chapters.includes(id)).slice(0,3).map(e=>`<a class="back" style="margin:8px 0" href="#exam/${e.id}">${e.title} →</a>`).join('')}</section></aside></div>`;}
function cardHTML(c,compact=false){const r=state.cards[c.id];const reveal=shown.has(c.id);return `<section class="question-card" data-card="${c.id}"><div class="question-top"><span>${chapter(c.chapter).title} · ${c.type}</span><span>${r?['Inte kan','Delvis kan','Kan säkert'][r.rating]:'Inte bedömd'}</span></div><h3>${c.q}</h3><label class="answer-label" for="answer-${c.id}">Din förklaring ur minnet</label><textarea id="answer-${c.id}" data-draft="${c.id}" maxlength="12000" placeholder="Börja med vad som händer. Förklara sedan varför.">${esc(state.drafts[c.id]||'')}</textarea><label class="fine" style="display:flex;gap:8px;align-items:center;margin:12px 0"><input type="checkbox" data-spoken="${c.id}" ${spoken.has(c.id)?'checked':''}> Jag har svarat högt eller på papper</label><div class="actions"><button class="button secondary small" data-action="show-card" data-id="${c.id}">${reveal?'Dölj biologiska poänger':'Visa biologiska poänger'}</button><button class="quiet fine" data-action="unknown-card" data-id="${c.id}">Jag vet inte ännu</button></div><div class="answer-model" ${reveal?'':'hidden'}><span class="eyebrow">JÄMFÖR MED DIN FÖRKLARING</span><p>${c.a}</p></div><div class="confidence" ${reveal?'':'hidden'} aria-label="Självskatta frågan">${[0,1,2].map((v,i)=>`<button data-action="rate" data-id="${c.id}" data-rating="${v}" aria-pressed="${r?.rating===v}">${['Inte kan','Delvis kan','Kan säkert'][i]}</button>`).join('')}</div>${compact&&reveal?'<p class="fine" style="margin:14px 0 0">Bedöm vad du kunde före facit. En säker markering är en självskattning, inte ett betyg.</p>':''}</section>`;}
function diagnostic(){const ids=['c1','m2','o1','a2','b1','r2','v2'];const c=C.cards.find(x=>x.id===ids[diagnosticPos]);return `${title('SNABBDIAGNOS · UTAN FACIT FÖRST','Börja där du är.','Försök cirka en minut per fråga. ”Inte kan” är användbar information. Självskattningen hjälper planen att prioritera.')}<div class="progress-track" role="progressbar" aria-label="Frågor i snabbdiagnosen" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${diagnosticPos}"><span style="width:${diagnosticPos/7*100}%"></span></div><p class="fine space-top">Fråga ${diagnosticPos+1} av 7</p><div class="reading-width">${cardHTML(c,true)}<div class="actions"><button class="button secondary" data-action="diag-back" ${diagnosticPos===0?'disabled':''}>← Förra</button><button class="button" data-action="diag-next">${diagnosticPos===6?'Spara diagnosen och fortsätt':'Nästa område →'}</button></div></div>`;}
function reviewPage(){if(!review){const list=E.dueCards(state,C,reviewFilter,reviewChapter);review={ids:list.map(x=>x.id).slice(0,8),pos:0};}const c=C.cards.find(x=>x.id===review.ids[review.pos]);const missed=C.exams.filter(e=>{const a=state.exams[e.id];return a&&a.checks.some(v=>!v)});return `${title('ÅTERKALLA · JÄMFÖR · FÖRSÖK IGEN','Repetera där det gör skillnad.','Högst åtta frågor per varv. Okända och osäkra frågor, förfallna repetitioner och områden med missade provpoänger prioriteras.')}<div class="filter-row"><label for="review-filter">Visa</label><select id="review-filter"><option value="weak" ${reviewFilter==='weak'?'selected':''}>Mina luckor och dagens repetition</option><option value="due" ${reviewFilter==='due'?'selected':''}>Bara förfallna repetitioner</option><option value="unseen" ${reviewFilter==='unseen'?'selected':''}>Bara oprövade frågor</option><option value="all" ${reviewFilter==='all'?'selected':''}>Alla kärnfrågor</option></select><label for="review-chapter">Område</label><select id="review-chapter"><option value="">Alla sju områden</option>${C.chapters.map(x=>`<option value="${x.id}" ${reviewChapter===x.id?'selected':''}>${x.title}</option>`).join('')}</select></div>${c?`<p class="fine">Fråga ${review.pos+1} av ${review.ids.length} i det här varvet · försök först utan stöd</p><div class="reading-width">${cardHTML(c,true)}<div class="actions"><button class="button secondary" data-action="review-prev" ${review.pos===0?'disabled':''}>← Förra</button><button class="button" data-action="review-next">${review.pos===review.ids.length-1?'Avsluta varvet':'Nästa fråga →'}</button></div></div>`:`<div class="empty"><h2>${review.ids.length?'Varvet är klart.':'Inga frågor i det valda urvalet.'}</h2><p>${review.ids.length?'Ta en paus och återkom. Använd sedan kunskapen i en öppen fråga.':'Om en repetition inte är förfallen ännu kan du välja alla kärnfrågor eller skriva ett eget provsvar.'}</p><div class="actions" style="justify-content:center"><button class="button secondary" data-action="review-new">Nytt varv</button>${button('Till provträningen','exams')}</div></div>`}${missed.length?`<section class="card space-top"><h3>Gå tillbaka till missade provpoänger</h3><p>En kärnfråga kan vara säker samtidigt som en tillämpning behöver mer träning. Försök svara igen före facit.</p>${missed.map(e=>`<a class="back" style="margin:7px 12px 7px 0" href="#exam/${e.id}">${e.title} →</a>`).join('')}</section>`:''}<p class="fine space-top">Nästa repetition föreslås efter ungefär 10 minuter (Inte kan), 4 timmar (Delvis kan) eller 18 timmar (Kan säkert). Det är en enkel, synlig regel. Variera frågor och förhör dig efter en paus.</p>`;}
function examsPage(filter=''){if(filter)examFilter=filter;const list=C.exams.filter(e=>!examFilter||e.chapters.includes(examFilter));return `${title('PROVTRÄNING – SIKTA MOT A','Skriv själv. Utveckla sedan.','Öppna scenarier med flera möjliga resonemang. Börja med frågorna 2, 4 och 3 i standardprogrammet. Modellsvaren visar möjliga svar; checklistan är ingen officiell betygsgräns.')}<div class="info-strip">${icon('pen')}Använd kedjan: påstående → mekanism → konsekvens → relevant villkor. Precision och välgrundade samband väger mer än fler ord.</div><div class="filter-row"><label for="exam-chapter">Filtrera område</label><select id="exam-chapter"><option value="">Alla sju områden</option>${C.chapters.map(x=>`<option value="${x.id}" ${examFilter===x.id?'selected':''}>${x.title}</option>`).join('')}</select></div><div class="exam-list">${list.map(e=>{const a=state.exams[e.id];return `<article class="card"><div class="question-top"><span>FRÅGA ${C.exams.indexOf(e)+1} · ${e.minutes} MIN SKRIVTID</span><span>${a?a.checks.filter(Boolean).length+'/'+e.points.length+' poänger med':'Eget svar först'}</span></div><h2>${e.title}</h2><p>${e.q}</p><div class="term-cloud">${e.chapters.map(x=>`<span>${chapter(x).title}</span>`).join('')}</div>${button(a?'Träna igen':'Öppna frågan','exam/'+e.id,'secondary small')}</article>`}).join('')}</div>`;}
function examPage(id){const e=C.exams.find(x=>x.id===id);if(!e)return missing();const reveal=shown.has(e.id),saved=state.exams[e.id];const checks=examChecks[e.id]??saved?.checks??e.points.map(()=>false);return `${back('Alla öppna provfrågor','exams')}${title('PROVTRÄNING – SIKTA MOT A · '+e.minutes+' MIN SKRIVTID',e.title,'Skriv först utan stöd. Lägg sedan 5–7 minuter på att jämföra, självbedöma och skriva om det viktigaste du missade.')}<div class="exam-prompt">${e.q}</div><div class="exam-grid"><section><label class="answer-label" for="exam-answer">Ditt eget svar · sparas automatiskt lokalt</label><textarea class="exam-answer" id="exam-answer" data-draft="${e.id}" maxlength="40000" placeholder="Börja med den biologiska processen. Skriv orsak → mekanism → följd. Lägg till ett villkor när det behövs.">${esc(state.drafts[e.id]||'')}</textarea><label class="fine" style="display:flex;gap:8px;align-items:center;margin:12px 0"><input type="checkbox" data-spoken="${e.id}" ${spoken.has(e.id)?'checked':''}> Jag har formulerat mitt svar högt eller på papper</label><div class="actions"><button class="button" data-action="show-exam" data-id="${e.id}">${reveal?'Stäng modellsvar och självbedömning':'Öppna modellsvar och självbedömning'}</button><button class="quiet fine" data-action="unknown-exam" data-id="${e.id}">Jag kommer inte igång – visa stöd</button></div><section id="exam-feedback" ${reveal?'':'hidden'}><div class="answer-model"><span class="eyebrow">ETT MÖJLIGT SVAR PÅ HÖG NIVÅ</span><p>${e.model}</p></div><div class="feedback-section"><h3>Från ytligt till utvecklat</h3><p>${e.develop}</p></div><div class="feedback-section"><h3>Begrepp som gör jobbet</h3><div class="term-cloud">${e.terms.map(t=>`<span>${t}</span>`).join('')}</div></div><div class="misconception"><h3>Undvik det här misstaget</h3><p style="font-size:14px;margin:0">${e.mistake}</p></div><section class="card"><h3>Vilka centrala poänger fanns i ditt svar?</h3><p>Markera bara det du faktiskt förklarade före facit. En annan korrekt formulering kan uppfylla samma poäng. Tom ruta betyder att poängen saknades eller var osäker.</p><div class="self-check">${e.points.map((p,i)=>`<label><input type="checkbox" data-exam-check="${e.id}" data-index="${i}" ${checks[i]?'checked':''}><span>${p[1]}</span></label>`).join('')}</div><button class="button" data-action="save-exam" data-id="${e.id}">Spara min självbedömning</button><p id="exam-save-result" class="fine space-top">${saved?'Senast sparat: '+saved.checks.filter(Boolean).length+' av '+e.points.length+' centrala poänger.':''}</p></section><div class="feedback-section"><h3>Gör kunskapen till din</h3><p>Stäng modellen. Skriv två egna meningar som reparerar den viktigaste luckan. Försök sedan med ett annat scenario. Poängräkningen är till för repetition och kan inte översättas till betyget A.</p></div></section></section><aside class="card"><span class="eyebrow">STÖD FÖR DITT RESONEMANG</span><h3>Fyra frågor att ställa</h3><p>1. Vilken mekanism efterfrågas?</p><p>2. Vad orsakar vad?</p><p>3. Vilka delar hänger ihop?</p><p>4. Vilket villkor kan ändra slutsatsen?</p><hr><p class="fine">Titta inte på modellsvar förrän du har försökt själv. Du behöver inte samma formulering för att ha rätt.</p>${e.chapters.map(x=>`<a class="back" href="#chapter/${x}">${chapter(x).title} →</a>`).join('')}</aside></div>`;}
function connectionsPage(id){const list=id?C.connections.filter(x=>x.id===id):C.connections;return `${id?back('Alla biologiska samband','connections'):''}${title('BIOLOGISKA SAMBAND – FÖRSTÅ HELHETEN','Samma mekanism. Fler möjliga svar.','Säg kedjan själv, kontrollera varje pil och prova den sedan i en öppen fråga. Koppla bara sådant som hjälper dig förklara det som efterfrågas.')}<div class="connection-grid">${list.map(s=>`<article class="card connection-card"><div class="term-cloud">${s.chapters.map(x=>`<span>${chapter(x).title}</span>`).join('')}</div><h2>${s.title}</h2><div class="chain">${s.chain.map((v,i)=>`${i?'<b aria-hidden="true">→</b>':''}<span>${v}</span>`).join('')}</div><p><strong>Varför sambandet spelar roll:</strong> ${s.why}</p><p><strong>I ett provsvar:</strong> ${s.use}</p><details class="details-block"><summary>Jämför ett enkelt och ett utvecklat resonemang</summary><div class="comparison"><div><small>ENKEL START</small><p>${s.basic}</p></div><div><small>UTVECKLAD ORSAKSKEDJA</small><p>${s.advanced}</p></div></div><div class="term-cloud">${s.terms.map(t=>`<span>${t}</span>`).join('')}</div></details>${button('Använd sambandet i en provfråga','exam/'+s.exam,'secondary small')}</article>`).join('')}</div>`;}
function progress(){const stats=C.chapters.map(c=>({c,s:E.chapterStats(state,C,c.id)}));return `${title('DINA KUNSKAPSLUCKOR','Visa det du kan förklara.','Läsning och genomförda uppgifter är aktiviteter. Kärnfrågorna och dina egna svar ger en mer användbar bild av vad du behöver återkomma till. All kunskapsnivå här är självskattad.')} ${statsHTML()}<div class="weak-list">${stats.map(({c,s})=>`<article class="weak-row"><span class="topic-number">${c.n}</span><div><h3>${c.title}</h3><p>${s.unknown} oprövade · ${s.total-s.secure-s.unknown} osäkra · ${s.missed} missade provpoänger</p><div class="progress-track"><span style="width:${s.secure/s.total*100}%"></span></div></div><strong>${s.secure}<small class="fine"> / ${s.total}</small></strong><a class="button secondary small" href="#review/${c.id}">Repetera →</a></article>`).join('')}</div><section class="card"><h3>Hur repetitionen prioriteras</h3><p>Oprövade och osäkra frågor kommer före redan säkra. En missad provpoäng gör området mer angeläget, även om kärnfrågorna känns lätta. Säkra frågor kommer tillbaka efter tid. En trygg markering efter att du precis sett facit är svagare underlag än en förklaring som fungerar efter en paus.</p><p class="fine">Inga sökord eller språkmodeller betygsätter ditt svar. Checklistan gör bedömningen synlig. ”Trygg” betyder din egen säkerhet, inte verifierad behärskning.</p></section>`;}
function sources(){return `${title('TRANSPARENS & KVALITET','Byggd på ditt material. Granskad för förståelse.','Kursen omfattar enbart de sju angivna områdena. Öppna frågor är en rimlig träningsinriktning utifrån din uppgift, inte verifierad information om lärarens prov.')}<section class="card"><h3>Så valdes innehållet</h3><p>Prioriteten bygger på fyra bedömningar: centralitet, användbarhet i flera frågor, betydelse som förkunskap och rimlig inlärningstid. Gradienter och membrantransport får stor vikt eftersom de förklarar många nya situationer. Cellens baskunskaper och alla sju områden behålls. Uppskattade minuter är riktmärken, inte uppmätta individuella inlärningstider.</p><div class="table-wrap"><table><thead><tr><th>Område / aktivitet</th><th>Riktmärke</th><th>Huvudnytta</th></tr></thead><tbody>${C.chapters.map(c=>`<tr><td>${c.title}</td><td>${c.minutes} min</td><td>${c.why}</td></tr>`).join('')}<tr><td>Diagnos, blandad repetition och självständig provträning</td><td>85 min</td><td>Återkallning över tid, överföring och återkoppling</td></tr><tr><td><strong>Totalt</strong></td><td><strong>360 min</strong></td><td>De sju ämnesandelarna summerar till 275 minuter; övrig träning till 85.</td></tr></tbody></table></div><p class="fine">Ämnesandelarna överlappar i sambandsövningar. I det konkreta schemat är varje minut bokförd en gång och pauserna anges separat. Miniprogrammet använder 180 minuter; extraprogrammet 450.</p></section><section class="card space-top"><h3>Vad som faktiskt granskades i originalet</h3><p>Källfilens inbäddade HTML-sidor för celler, membran, osmos, aktiv transport, mikrober, antibiotika och växtcell: rubriker, faktatexter, ordlistor, flashcards, quiz och deras förklaringar, diagrammens etiketter och interaktionernas kod. Dessa beskriver bok, filmer och PPT. Originalens PowerPoint-filer, hela filmer och ursprungliga bokfoton var inte separat tillgängliga som kompletta primärkällor här; täckningen bygger på vad Biologiatlas återger.</p><p>Överlappande flashcards har sammanförts till 28 kärnfrågor. Långa listor, gamla statistiktal och detaljmått ligger efter mekanismerna. Alla obligatoriska aktiviteter är kopplade till de sju områdena.</p></section><section class="card space-top"><h3>Viktiga preciseringar jämfört med originalet</h3><ul style="font-size:14px"><li>Osmolalitet mäts per kg lösningsmedel. Tonicitet beror på membranets permeabilitet, och tryck kan motverka osmos.</li><li>En växtcell i isoton miljö är relativt slapp; hög turgor kräver en lämplig vattenpotentialskillnad och väggens motstånd.</li><li>Kanaler driver inte riktat flöde. Pumpar har energibegränsningar; jontransport påverkas av elektrisk spänning.</li><li>Plasmider kan ha stabiliserande system. Resistens försvinner inte säkert när antibiotika tas bort.</li><li>Antibiotikans effekt kan vara tillväxthämmande. Råd om dos och behandlingstid är att följa ordination, inte att generellt ta högre dos eller längre kur.</li><li>Herpeslatens är inte samma sak som fagers lysogeni. Virusinträde kan ske på olika sätt.</li><li>Växtceller har mitokondrier och alla har inte kloroplaster. Spektrin hör till cellens inre stöd, inte ECM.</li><li>Originalets gamla art-, biomassa-, malaria- och bakterieantal används inte som provsanningar eller aktuella fakta. Äldre protistindelning märks som traditionell.</li></ul></section><section class="card space-top"><h3>Vad betyder ”sikta mot A” här?</h3><p>Att träna precis begreppsanvändning, förklarade orsakssamband, tillämpning i nya situationer och relevanta villkor. En modelltext är ett exempel, ingen garanti för en viss provpoäng eller ett kursbetyg. Läraren bedömer uppgiftens krav och elevens samlade kunskaper. Planen kan hjälpa dig utnyttja sex timmar väl men lovar inte att ersätta en hel kurs.</p></section><div class="section-top"><h2>Källor och kontrollunderlag</h2></div><div class="source-list">${C.sources.map(([h,u,p])=>`<article class="card"><a href="${u}" target="_blank" rel="noopener noreferrer">${h} ↗</a><p>${p}</p></article>`).join('')}</div><p class="fine space-top">Material och kod sammanställda för 2–3 november 2026. Innehållet är omformulerat och nya frågor är skapade för den här kursen. Ingen del av Biologiatlas har skrivits över.</p>`;}
function missing(){return `${title('SIDAN FINNS INTE','Välj nästa steg.','Den här länken kunde inte hittas i kursen.')} ${button('Till överblicken','home')}`;}
function render(){const raw=decodeURIComponent(location.hash.slice(1)||'home');const parts=raw.split('/');const old=route;route=raw;if(parts[0]!=='review')review=null;if(parts[0]==='review'&&parts[1]&&reviewChapter!==parts[1]){reviewChapter=chapter(parts[1])?parts[1]:'';review=null;}
  let html,crumb;switch(parts[0]){case'home':html=home();crumb='Din överblick';break;case'plan':html=plan();crumb='Din studieplan';break;case'session':html=sessionPage(parts[1]);crumb='Studieplan / Pass '+parts[1];break;case'course':html=course();crumb='De sju områdena';break;case'chapter':html=chapterPage(parts[1]);crumb='Kursen / '+(chapter(parts[1])?.title||'Område');break;case'diagnostic':html=diagnostic();crumb='Snabbdiagnos';break;case'review':html=reviewPage();crumb='Fokuserad repetition';break;case'exams':html=examsPage(parts[1]);crumb='Provträning – sikta mot A';break;case'exam':html=examPage(parts[1]);crumb='Provträning / Eget svar';break;case'connections':html=connectionsPage();crumb='Biologiska samband';break;case'connection':html=connectionsPage(parts[1]);crumb='Biologiskt samband';break;case'progress':html=progress();crumb='Dina kunskapsluckor';break;case'sources':html=sources();crumb='Källor & avgränsning';break;default:html=missing();crumb='Kursen';}
  $('#main').innerHTML=html;$('#breadcrumb').textContent=crumb;document.title=crumb+' · Biologi 2';renderNav();if(parts[0]==='chapter'&&parts[1]==='osmos')updateOsmosis(300);if(old!==route){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}if(parts[2]==='test')$('#chapter-questions')?.scrollIntoView({block:'start'});else if(parts[2]?.startsWith('step-'))$('#'+parts[2])?.scrollIntoView({block:'start'});
}
function renderNav(){const p=route.split('/')[0];const items=[['home','Överblick','home',['home']],['plan','Studieplan','plan',['plan','session','diagnostic']],['course','Kursen','book',['course','chapter']],['exams','Provträning','pen',['exams','exam']],['connections','Samband','link',['connections','connection']],['review','Repetition','repeat',['review','progress']]];$('#nav').innerHTML=items.map(([path,label,ico,active])=>`<a href="#${path}" class="${active.includes(p)?'active':''}" ${active.includes(p)?'aria-current="page"':''}>${icon(ico)}<span class="nav-text">${label}</span>${path==='review'?`<span class="nav-count">${E.dueCards(state,C).length}</span>`:''}</a>`).join('')+`<a href="#progress" class="${p==='progress'?'active':''}" style="${window.innerWidth<=900?'display:none':''}">${icon('check')}<span class="nav-text">Mina luckor</span></a>`;}
function updateOsmosis(value){const v=+value;$('#osm-value').textContent=v;const kind=v<300?'hypo':v>300?'hyper':'iso';const r=kind==='hypo'?55:kind==='hyper'?31:43;$('#rbc').setAttribute('rx',r);$('#rbc').setAttribute('ry',kind==='hypo'?50:kind==='hyper'?24:35);$('#rbc-center').setAttribute('rx',kind==='hypo'?35:kind==='hyper'?14:21);$('#rbc-center').setAttribute('ry',kind==='hypo'?32:kind==='hyper'?10:15);const shrink=kind==='hyper'?21:0;const m=$('#plant-membrane');m.setAttribute('x',49+shrink);m.setAttribute('y',33+shrink*.7);m.setAttribute('width',122-2*shrink);m.setAttribute('height',99-1.4*shrink);const vac=$('#vacuole');vac.setAttribute('x',kind==='hyper'?87:kind==='hypo'?57:66);vac.setAttribute('y',kind==='hyper'?59:kind==='hypo'?40:48);vac.setAttribute('width',kind==='hyper'?46:kind==='hypo'?106:88);vac.setAttribute('height',kind==='hyper'?47:kind==='hypo'?85:69);const flow=kind==='hypo'?'Vatten → in':kind==='hyper'?'Vatten → ut':'Inget bestående nettoflöde';$('#rbc-flow').textContent=flow;$('#plant-flow').textContent=kind==='hypo'?'Inflöde → ökad turgor':flow;const msgs={hypo:['Hypoton omgivning','Vatten går först netto in i båda celltyperna. Blodkroppen sväller och kan vid tillräcklig belastning spricka. Växtcellen får högre turgor; väggens mottryck kan till slut balansera drivkraften.'],iso:['Isoton referens','Blodkroppens volym är stabil i den förenklade modellen. Växtcellen är relativt slapp. Vattenmolekyler passerar fortfarande åt båda håll.'],hyper:['Hyperton omgivning','Vatten lämnar cellerna. Blodkroppen krymper; växtcellen tappar turgor och membranet kan dra sig från väggen: plasmolys. Storleken är kvalitativ och inte beräknad från reglaget.']};$('#osm-result').innerHTML=`<h4>${msgs[kind][0]}</h4><p>${msgs[kind][1]}</p>`;}
function repaintCard(id){const c=C.cards.find(x=>x.id===id),el=document.querySelector(`[data-card="${id}"]`);if(c&&el)el.outerHTML=cardHTML(c,route==='diagnostic'||route.startsWith('review'));}
function openSettings(){pauseTimer(false);$('#remaining').value=E.remain(state);$('#focus-length').value=state.focusLength;$('#settings').showModal();}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;switch(action){
  case'settings':openSettings();break;
  case'programme':pauseTimer(false);state.budget=state.studiedSeconds/60+Number(b.dataset.minutes);save();render();toast('Planen utgår nu från '+b.dataset.minutes+' minuter kvar.');break;
  case'day':day=Number(b.dataset.day);render();break;
  case'focus':if(!running)startTimer();toast('Fokustimern är igång. Pauser räknas inte.');break;
  case'show-card':if(shown.has(id)){shown.delete(id);repaintCard(id);break;}if(!(state.drafts[id]||'').trim()&&!spoken.has(id)){toast('Försök först själv, eller välj ”Jag vet inte ännu”.');return;}shown.add(id);repaintCard(id);break;
  case'unknown-card':shown.add(id);E.rate(state,id,0);save();repaintCard(id);renderNav();break;
  case'rate':E.rate(state,id,Number(b.dataset.rating));save();repaintCard(id);renderNav();toast('Självskattningen sparad. Försök igen efter en paus.');break;
  case'diag-back':diagnosticPos=Math.max(0,diagnosticPos-1);render();break;
  case'diag-next':{const ids=['c1','m2','o1','a2','b1','r2','v2'];if(!state.cards[ids[diagnosticPos]]){toast('Välj Inte kan, Delvis kan eller Kan säkert innan du går vidare.');return;}if(diagnosticPos<6){diagnosticPos++;render();}else{state.diagnosed=true;state.tasks.diagnos=true;save();navigate('plan');toast('Diagnosen sparad. Planen prioriterar dina luckor.');}break;}
  case'review-prev':review.pos=Math.max(0,review.pos-1);render();break;
  case'review-next':{const current=review?.ids[review.pos];if(current&&!state.cards[current]){toast('Självskatta frågan innan du går vidare.');return;}review.pos++;render();window.scrollTo(0,0);break;}
  case'review-new':shown.clear();review=null;render();break;
  case'show-exam':if(shown.has(id)){shown.delete(id);$('#exam-feedback').hidden=true;b.textContent='Öppna modellsvar och självbedömning';break;}if(!(state.drafts[id]||'').trim()&&!spoken.has(id)){toast('Formulera först ett eget svar, eller välj stödet om du inte kommer igång.');return;}shown.add(id);$('#exam-feedback').hidden=false;b.textContent='Stäng modellsvar och självbedömning';break;
  case'unknown-exam':shown.add(id);examChecks[id]=C.exams.find(x=>x.id===id).points.map(()=>false);render();toast('Utgå från orsakskedjan. Spara tomma rutor för det du inte kunde.');break;
  case'save-exam':{const e=C.exams.find(x=>x.id===id);const checks=[...document.querySelectorAll(`[data-exam-check="${id}"]`)].map(x=>x.checked);if(checks.length!==e.points.length)return;state.exams[id]={checks,at:Date.now()};examChecks[id]=checks;save();$('#exam-save-result').textContent=`Sparat: ${checks.filter(Boolean).length}/${checks.length} poänger. ${checks.some(v=>!v)?'Missade poänger prioriterar motsvarande områden i repetitionen.':'Försök nu på ett nytt scenario utan facit.'}`;toast('Självbedömningen är sparad.');break;}
  case'osm-preset':$('#osm-range').value=b.dataset.value;updateOsmosis(b.dataset.value);break;
  case'pump-next':pumpPos=(pumpPos+1)%pumpSteps.length;$('#pump-lab').innerHTML=pumpLab();break;
  case'pump-prev':pumpPos=Math.max(0,pumpPos-1);$('#pump-lab').innerHTML=pumpLab();break;
}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.draft){state.drafts[el.dataset.draft]=el.value;save();}if(el.id==='osm-range')updateOsmosis(el.value);if(el.id==='course-search'){courseFilter=el.value;$('#topic-results').innerHTML=filteredChapters();}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;save();}if(el.dataset.spoken){el.checked?spoken.add(el.dataset.spoken):spoken.delete(el.dataset.spoken);}if(el.dataset.examCheck){const id=el.dataset.examCheck;examChecks[id]=[...document.querySelectorAll(`[data-exam-check="${id}"]`)].map(x=>x.checked);}if(el.id==='review-filter'){reviewFilter=el.value;review=null;shown.clear();render();}if(el.id==='review-chapter'){reviewChapter=el.value;review=null;shown.clear();if(route.split('/')[1])navigate('review');else render();}if(el.id==='exam-chapter'){examFilter=el.value;if(route.split('/')[1])navigate('exams');else render();}});
$('.skip').addEventListener('click',ev=>{ev.preventDefault();$('#main').focus();});
$('#settings-open').addEventListener('click',openSettings);
$('#remaining-save').addEventListener('click',()=>{const n=Number($('#remaining').value);if(!Number.isFinite(n)||n<5||n>1440){toast('Ange 5–1440 effektiva minuter.');return;}state.budget=state.studiedSeconds/60+n;state.focusLength=Number($('#focus-length').value);timerLeft=state.focusLength*60;save();updateTimer();$('#settings').close();review=null;render();toast('Din tidsbudget är uppdaterad.');});
$('#focus-length').addEventListener('change',()=>{state.focusLength=Number($('#focus-length').value);pauseTimer(false);timerLeft=state.focusLength*60;save();updateTimer();});
function download(name,text){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').addEventListener('click',()=>{save();download('biologi2-framsteg.json',JSON.stringify(state,null,2));toast('Säkerhetskopian har exporterats.');});
$('#import').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>1500000)throw Error('Filen är för stor. Välj en säkerhetskopia från kursen.');const next=E.validateImport(JSON.parse(await f.text()),C);if(!confirm('Ersätt den lokala progressionen med säkerhetskopian? Exportera först om du vill behålla båda.'))return;pauseTimer(false);state=next;review=null;shown.clear();examChecks={};timerLeft=state.focusLength*60;save();render();updateTimer();$('#settings').close();toast('Säkerhetskopian har importerats.');}catch(error){toast(error.message||'Kunde inte läsa filen.');}finally{ev.target.value='';}});
$('#reset-progress').addEventListener('click',()=>{if(!confirm('Radera alla dina sparade svar och markeringar på den här adressen?'))return;pauseTimer(false);state=E.fresh();review=null;shown.clear();spoken.clear();examChecks={};diagnosticPos=0;timerLeft=25*60;save();$('#settings').close();navigate('home');render();updateTimer();toast('Den lokala progressionen har raderats.');});
let timerLeft=state.focusLength*60,running=false,lastTick=0,timerInterval=null;
function updateTimer(){const n=Math.max(0,Math.ceil(timerLeft));$('#timer-display').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');$('#timer-toggle').textContent=running?'Ⅱ':'▶';$('#timer-toggle').setAttribute('aria-label',running?'Pausa fokustimer':'Starta fokustimer');}
function tick(){if(!running)return;const now=performance.now();const delta=Math.min((now-lastTick)/1000,timerLeft);lastTick=now;if(document.hidden){pauseTimer(true);return;}timerLeft-=delta;state.studiedSeconds+=delta;updateTimer();document.querySelectorAll('[data-remaining-display]').forEach(el=>el.textContent=formatMinutes(E.remain(state)));if(timerLeft<=0){pauseTimer(false);toast('Fokusblocket är klart. Ta en paus och återkalla sedan en sak utan stöd.');}if(Math.floor(state.studiedSeconds)%5===0)save();}
function startTimer(){if(timerLeft<=0)timerLeft=state.focusLength*60;running=true;lastTick=performance.now();clearInterval(timerInterval);timerInterval=setInterval(tick,250);updateTimer();}
function pauseTimer(tell){if(running){running=false;clearInterval(timerInterval);save();updateTimer();if(tell)toast('Timern pausades när du lämnade sidan.');}}
$('#timer-toggle').addEventListener('click',()=>running?pauseTimer(false):startTimer());$('#timer-reset').addEventListener('click',()=>{pauseTimer(false);timerLeft=state.focusLength*60;updateTimer();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseTimer(true);});window.addEventListener('beforeunload',()=>{pauseTimer(false);save();});
window.addEventListener('hashchange',()=>{shown.clear();spoken.clear();if(!location.hash.startsWith('#review'))review=null;render();});
window.addEventListener('resize',renderNav);render();updateTimer();
})();
